/**
 * Amazon Integration Module
 *
 * Host wiring for the Amazon plugin, generated by `createNestAdapterModule`
 * (the LWA token is minted statelessly and cached through the host
 * `CachePort`). The Nest-provided pieces are the notification provisioner and
 * the scheduler tasks filtered by connection config, which need
 * `ConnectionPort` (#4179, #4180).
 *
 * Wired into `apps/api/src/plugins.ts` and `apps/worker/src/plugins.ts`.
 *
 * @module libs/integrations/amazon/src
 */
import type { DynamicModule } from '@nestjs/common';
import { createNestAdapterModule } from '@openlinker/plugin-sdk';

import { createAmazonPlugin } from './amazon-plugin';
import { AmazonHostModule } from './amazon-host.module';

export const AmazonIntegrationModule: DynamicModule = createNestAdapterModule({
  plugin: createAmazonPlugin(),
  // #4179 / #4180: the "Configure webhooks" action and the scheduler tasks
  // whose connection filter reads the config (all need ConnectionPort).
  imports: [AmazonHostModule],
});
